	array(
		'question_text'  => 'Midway through treatment, a client questions a newly proposed intervention and asks whether the intake agreement permanently controls future decisions. Which statement best describes ongoing informed consent in psychotherapy?',
		'option_a'       => 'The therapist must repeat every intake disclosure at every session.',
		'option_b'       => 'The therapist should revisit relevant information when material treatment changes, new concerns, or client questions arise.',
