	),
	array(
		'question_text'  => 'Four months into treatment, a client asks why a particular intervention is being used and whether other approaches are available. What should the therapist do?',
		'option_a'       => 'Explain that treatment questions must be raised during intake.',
		'option_b'       => 'Refer the client only to the original signed agreement.',
